#nullable disable

using System;
using System.Collections.Generic;
using OpenAI.Responses;

namespace Azure.AI.Extensions.OpenAI;

[CodeGenSerialization("ResponseIdInternal", SerializationName = "response_id")]
[CodeGenSerialization("AgentReferenceInternal", SerializationName = "agent_reference")]
public partial class A2AToolCall
{
    /// <summary> Initializes a new instance of <see cref="A2AToolCall"/>. </summary>
    /// <param name="callId"> The unique ID of the tool call generated by the model. </param>
    /// <param name="name"> The name of the A2A agent card being called. </param>
    /// <param name="arguments"> A JSON string of the arguments to pass to the tool. </param>
    /// <param name="status"> The status of the tool call. </param>
    public A2AToolCall(string callId, string name, string arguments, ToolCallStatus status) : base(ResponseItemKind.A2APreviewCall)
    {
        CallId = callId;
        Name = name;
        Arguments = arguments;
        Status = status;
    }

    /// <summary> Initializes a new instance of <see cref="A2AToolCall"/>. </summary>
    /// <param name="id"></param>
    /// <param name="agentReference"> The agent that created the item. </param>
    /// <param name="responseId"> The response on which the item is created. </param>
    /// <param name="callId"> The unique ID of the tool call generated by the model. </param>
    /// <param name="name"> The name of the A2A agent card being called. </param>
    /// <param name="arguments"> A JSON string of the arguments to pass to the tool. </param>
    /// <param name="status"> The status of the tool call. </param>
    /// <param name="additionalBinaryDataProperties"> Keeps track of any properties unknown to the library. </param>
    internal A2AToolCall(string id, AgentReference agentReference, string responseId, string callId, string name, string arguments, ToolCallStatus status, IDictionary<string, BinaryData> additionalBinaryDataProperties) : this(
        type: ResponseItemKind.A2APreviewCall,
        id: id,
        agentReference: agentReference,
        responseId: responseId,
        callId: callId,
        name: name,
        arguments: arguments,
        status: status,
        responseIdInternal: responseId,
        agentReferenceInternal: agentReference,
        additionalBinaryDataProperties: additionalBinaryDataProperties
        )
    {
    }

    /// <summary> Initializes a new instance of <see cref="A2AToolCall"/> for deserialization. </summary>
    internal A2AToolCall() : base(ResponseItemKind.A2APreviewCall)
    {
    }

    // Custom: the generated constructor passed (id, agentReference, responseId) to the
    // OpenAI ResponseItem base type, which only exposes a constructor taking the kind, causing
    // CS1729. Relocated here from the generated model and changed to call base(@type) only.
    /// <summary> Initializes a new instance of <see cref="A2AToolCall"/>. </summary>
    /// <param name="type"></param>
    /// <param name="id"></param>
    /// <param name="agentReference"> The agent that created the item. </param>
    /// <param name="responseId"> The response on which the item is created. </param>
    /// <param name="callId"> The unique ID of the tool call generated by the model. </param>
    /// <param name="name"> The name of the A2A agent card being called. </param>
    /// <param name="arguments"> A JSON string of the arguments to pass to the tool. </param>
    /// <param name="status"> The status of the tool call. </param>
    /// <param name="responseIdInternal">Duplicated field, generated by emitter.</param>
    /// <param name="agentReferenceInternal">Duplicated field, generated by emitter.</param>
    /// <param name="additionalBinaryDataProperties"> Keeps track of any properties unknown to the library. </param>

    internal A2AToolCall(ResponseItemKind @type, string id, AgentReference agentReference, string responseId, string callId, string name, string arguments, ToolCallStatus status, string responseIdInternal, AgentReference agentReferenceInternal, IDictionary<string, BinaryData> additionalBinaryDataProperties) : base(ResponseItemKind.A2APreviewCall)
    {
        this.ApplyAgentAttribution(agentReference, responseId, additionalBinaryDataProperties);
        Id = id;
        CallId = callId;
        Name = name;
        Arguments = arguments;
        Status = status;
        _additionalBinaryDataProperties = additionalBinaryDataProperties;
    }

    // Create properties to enable additional fields serialiuzation.
    internal string ResponseIdInternal { get => this.ResponseId; }
    internal AgentReference AgentReferenceInternal { get => this.AgentReference; }
}
